struct node { int data; struct node *prev, *next; };

void delete_node(struct node **L, struct node *p) {
    p->prev->next = p->next;   /* 前一個節點跳過 p */
    p->next->prev = p->prev;   /* 後一個節點跳過 p */
    if (*L == p)               /* 入口剛好是 p */
        *L = p->next;
    free(p);
}

